# Reusable ecological logic. Keep functions here independent of Shiny UI.

get_species <- function(community) {
  if (is.null(community)) return(character())
  cheddar::NPS(community)$node
}

remove_species_cascade <- function(community, species) {
  before <- get_species(community)

  if (length(before) == 0L) {
    return(list(
      community = NULL,
      primary = character(),
      secondary = character()
    ))
  }

  if (length(species) != 1L || !species %in% before) {
    stop("Please select a species that exists in the current food web.")
  }

  # Handle the final species separately to avoid cheddar edge cases.
  if (length(before) == 1L) {
    return(list(
      community = NULL,
      primary = species,
      secondary = character()
    ))
  }

  updated <- tryCatch(
    cheddar::RemoveNodes(community, remove = species, method = "cascade"),
    error = function(e) {
      # Do not silently treat every model error as total extinction.
      stop("The extinction cascade could not be calculated: ",
           conditionMessage(e), call. = FALSE)
    }
  )

  after <- get_species(updated)
  disappeared <- setdiff(before, after)

  list(
    community = if (length(after) == 0L) NULL else updated,
    primary = species,
    secondary = setdiff(disappeared, species)
  )
}

# Tab 1: primary and secondary extinction dynamics.

extinctionUI <- function(id) {
  ns <- NS(id)

  fluidPage(
    sidebarLayout(
      sidebarPanel(
        selectInput(
          ns("species_to_delete"),
          "Species to delete",
          choices = NULL
        ),
        actionButton(ns("evaluate"), "Evaluate"),
        actionButton(ns("reset"), "Refresh Food Web"),
        hr(),
        h4("☠️ Graveyard"),
        h5("Primary Extinctions"),
        uiOutput(ns("primary_extinct_list")),
        h5("Secondary Extinctions"),
        uiOutput(ns("secondary_extinct_list"))
      ),
      mainPanel(
        p(paste(
          "Choose a species to remove and observe how its extinction",
          "can trigger further losses through the food web."
        )),
        p(HTML(paste0(
          "<strong>PRIMARY EXTINCTION:</strong> A species is removed, ",
          "for example through environmental change or overharvesting."
        ))),
        p(HTML(paste0(
          "<strong>SECONDARY EXTINCTION:</strong> Additional species ",
          "disappear as a consequence of the initial removal."
        ))),
        plotOutput(ns("foodweb_plot"), height = "70vh")
      )
    ),
    hr(),
    tags$footer(
      class = "footer-credits",
      p(HTML(paste0(
        "<strong>Credits:</strong> Add the original species-image ",
        "attributions here before publishing."
      )))
    )
  )
}

extinctionServer <- function(id, initial_community) {
  moduleServer(id, function(input, output, session) {

    initial_species <- get_species(initial_community)
    img_list <- load_species_images(initial_species)

    state <- reactiveValues(
      community = initial_community,
      primary = character(),
      secondary = character()
    )

    observe({
      updateSelectInput(
        session,
        "species_to_delete",
        choices = get_species(state$community),
        selected = if (length(get_species(state$community))) {
          get_species(state$community)[1]
        } else {
          character(0)
        }
      )
    })

    observeEvent(input$evaluate, {
      req(input$species_to_delete)

      result <- tryCatch(
        remove_species_cascade(
          state$community,
          input$species_to_delete
        ),
        error = function(e) {
          showNotification(conditionMessage(e), type = "error")
          NULL
        }
      )

      if (is.null(result)) return()

      state$community <- result$community
      state$primary <- unique(c(state$primary, result$primary))
      state$secondary <- unique(c(state$secondary, result$secondary))
    }, ignoreInit = TRUE)

    observeEvent(input$reset, {
      state$community <- initial_community
      state$primary <- character()
      state$secondary <- character()
    }, ignoreInit = TRUE)

    output$primary_extinct_list <- renderUI({
      if (length(state$primary) == 0L) return(NULL)
      tags$ul(lapply(state$primary, function(sp) {
        tags$li(
          style = "color: red; text-decoration: line-through;",
          sp
        )
      }))
    })

    output$secondary_extinct_list <- renderUI({
      if (length(state$secondary) == 0L) return(NULL)
      tags$ul(lapply(state$secondary, function(sp) {
        tags$li(
          style = "color: gray; text-decoration: line-through;",
          sp
        )
      }))
    })

    output$foodweb_plot <- renderPlot({
      plot_foodweb(state$community, img_list)
    })
  })
}

# Load the plot list once when the app starts
connectance_plots <- readRDS("data/network_plots.rds")


connectanceUI <- function(id, n) {
  ns <- NS(id)

  fluidPage(
    sidebarLayout(
      sidebarPanel(
        sliderInput(
          ns("connectance"),
          "Connectance",
          min = 1,
          max = n,
          value = 1,
          step = 1,
          ticks = FALSE,
          animate = FALSE
        )
        ,
        fluidRow(
          column(6, tags$small("Low")),
          column(
            6,
            tags$small("High", style = "float: right;")
          )
        )
      ),

      mainPanel(
        plotOutput(ns("plot1"), height = "350px"),
        plotOutput(ns("plot2"), height = "350px")
      )
    )
  )
}


connectanceServer <- function(id) {
  moduleServer(id, function(input, output, session) {

    output$plot1 <- renderPlot({
      connectance_plots[[input$connectance]][1]
    })

    output$plot2 <- renderPlot({
      connectance_plots[[input$connectance]][2]
    })

  })
}

/* ===== FONTS ===== */
@import url('https://fonts.googleapis.com/css2?family=Audiowide&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Anton&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Raleway:wght@100..900&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Pacifico&display=swap');

/* ===== COLORS ===== */
/* 
primary   #042940
secondary #005C53
accent1   #DBF227
accent2   #DB8655
accent3   #62771B
black     #262406
white     #ffffff
*/

/* ===== BASE ===== */
body {
  background-color: #ffffff;
  color: #262406;
  font-family: 'Raleway', sans-serif;
}

a {
  color: #005C53;
}

/* ===== HEADINGS ===== */
h1 {
  color: #042940;
  font-family: 'Audiowide', sans-serif;
  font-size: 3rem;
  font-weight: 400;
}

h2 {
  color: #005C53;
  font-family: 'Raleway', sans-serif;
  font-size: 2rem;
  font-weight: 600;
}

h3 {
  color: #005C53;
  font-family: 'Raleway', sans-serif;
  font-size: 1.5rem;
  font-weight: 500;
}

/* ===== NAVBAR ===== */
.navbar {
  background-color: #042940 !important;
}

.navbar .navbar-brand {
  font-family: 'Audiowide', sans-serif;
  font-size: 2rem;
}

.navbar-nav .nav-link {
  color: #DB8655 !important;
  font-family: 'Raleway', sans-serif;
  font-size: 1.2rem;
}

.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
}

/* ===== RESEARCH QUESTION ===== */
.research-question {
  font-family: 'Raleway', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  color: #DB8655;
  text-transform: uppercase;
}

/* ===== SIDEBAR (Shiny wellPanel equivalent) ===== */
.well {
  background-color: #f8f9fa;
  border-radius: 10px;
  border: 1px solid #ddd;
}

/* ===== BUTTONS ===== */
.btn {
  background-color: #042940;
  color: #DBF227;
  border: none;
}

.btn:hover {
  background-color: #005C53;
  color: #DBF227;
}

/* ===== TEACHING LIST ===== */
.teaching .course-entry {
  display: flex;
  flex-direction: row;
  line-height: 1.3;
  margin-bottom: 3em;
  column-gap: 0.7em;
}

.teaching .course-entry .body {
  flex: 1 1 auto;
}

.teaching .course-entry .logo {
  flex: 0 0 140px;
}

.teaching .course-entry .logo img {
  width: 100%;
}

.teaching .course-entry .course-title {
  font-weight: 500;
  font-size: 1.25em;
}

.teaching .course-entry .course-details {
  font-weight: 300;
  font-size: 0.9em;
}

.teaching .course-entry .course-description {
  font-weight: 300;
  font-size: 1.1em;
}

.teaching .course-entry .course-role {
  font-weight: 500;
}

.teaching .course-entry ul.course-links {
  list-style: none;
  padding: 0;
}

.teaching .course-entry ul.course-links li {
  display: inline-block;
  background-color: #042940;
  margin: 0 0.2em 0.4em 0;
  padding: 0.2em 0.4em;
  font-size: 0.85em;
  border-radius: 0.25rem;
}

.teaching .course-entry ul.course-links li a {
  color: #DBF227;
  text-decoration: none;
}

/* ===== HERO ===== */
.hero-container {
  overflow: hidden;
  position: relative;
  max-height: 52vh;
  height: 52vh;
}

.hero-image {
  position: absolute;
  background-size: cover;
  height: 100%;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-repeat: no-repeat;
}

.hero-title-top {
  font-size: 100px;
  color: #ffffff;
  font-weight: bold;
}

.hero-title-bottom {
  font-size: 100px;
  color: #EEECEA;
  font-weight: bold;
}

/* ===== FOOTER ===== */
footer {
  background-color: #005C53;
  color: #DBF227;
  padding: 20px;
  text-align: center;
}

/* Footer credits */
.footer-credits {
  font-size: 0.85em;
  color: #DBF227;        /* accent1 (bright lime) */
  line-height: 1.5;
}

.footer-credits strong {
  color: #DB8655;        /* accent2 (warm highlight) */
}

/* ===== NavBar ===== */

.navbar {
  background-color: #042940 !important;
  padding-top: 15px;
  padding-bottom: 15px;
}

.navbar .navbar-brand {
  font-family: 'Audiowide', sans-serif;
  font-size: 1.5rem;
  color: #DB8655;
  display: flex;
  align-items: center;
}

.navbar-nav .nav-link {
  color: #DB8655 !important;
}

.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
}

/* NavBar logo */
.navbar-logo {
  height: 70px;
  margin-right: 10px;
}

/* ===== NAVBAR TABS ===== */

/* Make tabs look like part of navbar */
.navbar-nav .nav-link {
  color: #DB8655 !important;
  font-family: 'Raleway', sans-serif;
  font-size: 1.2rem;
  background: none !important;
  border: none !important;
}

/* Hover */
.navbar-nav .nav-link:hover {
  color: #DBF227 !important;
  background: none !important;
}

/* Active tab (THIS is the key one) */
.navbar-nav .nav-link.active,
.navbar-nav > .active > a {
  color: #DBF227 !important;
  background-color: transparent !important;
  border-bottom: 3px solid #DB8655;
}


/* Hide all numeric labels on Shiny sliders */
.irs-min,
.irs-max,
.irs-from,
.irs-to,
.irs-single,
.irs-grid-text,
.irs-grid-pol {
  display: none !important;
}

/* Also hide labels from newer slider implementations */
.shiny-input-container .slider-tick-label {
  display: none !important;
}


/* Hide the value bubble and min/max labels on Shiny sliders */
.irs--shiny .irs-min,
.irs--shiny .irs-max,
.irs--shiny .irs-from,
.irs--shiny .irs-to,
.irs--shiny .irs-single {
  display: none !important;
}
